#include <string>

int countSpaces(const std::string& text)
{
    int count{ 0 };
    for (char c : text)
    {
        if (c == ' ')
        {
            ++count;
        }
    }
    return count;
}

unitTests:
TEST("counts spaces") { CHECK_EQ(countSpaces("one two three"), 2); CHECK_EQ(countSpaces("a b c d e"), 4); }
TEST("no spaces") { CHECK_EQ(countSpaces("word"), 0); CHECK_EQ(countSpaces(""), 0); }
TEST("only spaces") { CHECK_EQ(countSpaces("   "), 3); }
TEST("takes a const reference") { static_assert(std::is_invocable_v<decltype(&countSpaces), const std::string&>); const std::string s{ "x y" }; CHECK_EQ(countSpaces(s), 1); }

